class Period:
    start: date
    end: date
    label: str          # testo che lo ha generato, es. "ottobre", "weekend"


@dataclass(frozen=True)
class Criteria:
    sport: Optional[str] = None
    area: Optional[Area] = None
    period: Optional[Period] = None
    pax: Optional[int] = None
    budget: Optional[Decimal] = None
    language: str = "it"


def criteria_to_dict(c: Criteria) -> dict:
    return {
        "sport": c.sport,
        "area": None if c.area is None else {"kind": c.area.kind, "name": c.area.name,
                                             "country_code": c.area.country_code},
        "period": None if c.period is None else {"start": c.period.start.isoformat(),
                                                 "end": c.period.end.isoformat(),
                                                 "label": c.period.label},
        "pax": c.pax,
        "budget": None if c.budget is None else money_str(c.budget),
        "language": c.language,
    }


def criteria_from_dict(d: dict) -> Criteria:
    area = d.get("area")
    period = d.get("period")
    budget = d.get("budget")
    return Criteria(
        sport=d.get("sport"),
        area=None if area is None else Area(area["kind"], area["name"], area["country_code"]),
        period=None if period is None else Period(date.fromisoformat(period["start"]),
                                                  date.fromisoformat(period["end"]),
                                                  period["label"]),
        pax=d.get("pax"),
        budget=None if budget is None else Decimal(budget),
        language=d.get("language") or "it",
    )


    title: str
    destination: Optional[str]
    hotel: Optional[str]

    def to_dict(self) -> dict:
        return {"product_id": self.product_id, "title": self.title,
                "destination": self.destination, "hotel": self.hotel}


@dataclass(frozen=True)
class IntentCreated:
    intent_id: str
    criteria: Criteria
    say: str

    def to_dict(self) -> dict:
        return {"intent_id": self.intent_id, "criteria": criteria_to_dict(self.criteria),
                "say": self.say}


@dataclass(frozen=True)
class IntentQuestion:
    question: str
    say: str

    def to_dict(self) -> dict:
        return {"question": self.question, "say": self.say}


@dataclass(frozen=True)
class ProposalMade:
    proposal: Proposal
    product: ProductSummary
    say: str
    replaced: bool = False

    def to_dict(self) -> dict:
        p = self.proposal
        return {"proposal_id": p.id, "intent_id": p.intent_id, "product": self.product.to_dict(),
                "start_date": p.start_date.isoformat(), "end_date": p.end_date.isoformat(),
                "pax": p.pax, "price_from": money_str(p.price_from),
                "total_from": money_str(p.total_from), "currency": p.currency,
                "reason": p.reason, "replaced": self.replaced, "say": self.say}


@dataclass(frozen=True)
class NoMatch:
    intent_id: str
    failed_criterion: str
    say: str

    def to_dict(self) -> dict:
        return {"intent_id": self.intent_id, "failed_criterion": self.failed_criterion,
                "say": self.say}


@dataclass(frozen=True)
class OrderQueued:
    """RF-45, RF-19: risposta dell'accettazione. Nessun link: arriva con `get_order_status`."""
    order_id: str
    status: OrderStatus
    position: Optional[int]
    wait_seconds: Optional[int]
    say: str

    def to_dict(self) -> dict:

_DIRECTIONS = {"south": SOUTH_OF, "north": NORTH_OF}


def find_area(text: Optional[str]) -> Optional[Area]:
    low = (text or "").lower()
    for pattern, area in _INDEX:
        if pattern.search(low):
            return area
    return None


def area_of_destination(title: Optional[str], country_code: Optional[str]) -> Optional[Area]:
    found = find_area(title)
    if found is not None:
        return found
    return country_area(country_code)


def country_area(code: Optional[str]) -> Optional[Area]:
    if code not in COUNTRIES:
        return None
    return Area("country", COUNTRIES[code], code)


def ancestors(area: Area) -> list:
    """L'area e chi la contiene, fino al paese: Palma de Mallorca → Maiorca → Baleari → Spagna."""
    chain = [area]
    while chain[-1].name in PARENTS:
        chain.append(_BY_NAME[PARENTS[chain[-1].name]])
    if area.kind != "country":
        country = country_area(area.country_code)
        if country is not None:
            chain.append(country)
    return chain


def common_region(a: Area, b: Area) -> Optional[Area]:
    """La prima area non nazionale che contiene sia `a` sia `b` (Lanzarote, Tenerife → Canarie)."""
    others = ancestors(b)
    for candidate in ancestors(a):
        if candidate.kind != "country" and candidate in others:
            return candidate
    return None


def where(area: Area, lang: str = "it") -> str:
    """Complemento di luogo: "in Spagna", "a Lanzarote", "alle Canarie"; in inglese "in Spain",
    "in the Canary Islands"."""
    if lang == "en":
        return _LOCATIVE_EN.get(area.name) or "in %s" % display_name(area, lang)
    if area.name in _LOCATIVE:
        return _LOCATIVE[area.name]
    return ("in %s" if area.kind == "country" else "a %s") % area.name


def area_by_name(name: Optional[str]) -> Optional[Area]:
    return _BY_NAME.get(name)


def display_name(area: Area, lang: str) -> str:
    return EN_NAMES.get(area.name, area.name) if lang == "en" else area.name


def move(area: Optional[Area], direction: str) -> Optional[Area]:
    """Area più a sud o più a nord di `area` (RF-08): prima la voce del luogo, poi quella del paese."""
    if area is None:
        return None
    table = _DIRECTIONS[direction]
    for key in (area.name, COUNTRIES.get(area.country_code)):
        if key in table:
            targets = table[key]
            return _BY_NAME[targets[0]] if targets else None
    return None

